package io.knowledgebrain.planning;
import java.time.*;import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.postgresql.ds.PGSimpleDataSource;import org.flywaydb.core.Flyway;import org.springframework.jdbc.core.JdbcTemplate;
import org.apache.kafka.clients.consumer.*;import io.knowledgebrain.contracts.planning.reminder.v1.*;
import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_PLANNING_KAFKA_BOOTSTRAP",matches=".+")
class ReminderKafkaIntegrationTest {
 @Test void committedReminderSnapshotsAndTraceHeadersArriveAsExactOutboxBytes()throws Exception{
  var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_PLANNING_DATABASE_URL"));ds.setUser("brain_planning");ds.setPassword(System.getenv("BRAIN_TEST_PLANNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();
  var ids=new UuidV7(Clock.systemUTC());var space=ids.next();var actor=ids.next();String trace="d".repeat(32),key=UUID.randomUUID().toString().replace("-","");var store=new ReminderStore(ds,Clock.systemUTC());
  var source=new ScheduleStore(ds,Clock.systemUTC()).create(space,actor,UUID.randomUUID().toString().replace("-",""),new ScheduleStore.Input("Kafka reminder pin","","2028-03-12T07:10:00Z","2028-03-12T08:10:00Z","America/New_York",null),trace).schedule();
  var input=new ReminderRules.Input(source.scheduleId(),1,20);var preview=store.preview(space,input);var original=store.create(space,actor,key,input,preview.previewHash(),trace).reminder();var changed=new ReminderRules.Input(source.scheduleId(),1,30);var next=store.change(space,original.reminderId(),actor,1,changed,store.preview(space,changed).previewHash(),false,trace);var retired=store.change(space,original.reminderId(),actor,2,null,null,true,trace);assertEquals(original,store.create(space,ids.next(),key,input,preview.previewHash(),trace).reminder());
  var expected=new HashMap<String,byte[]>();new JdbcTemplate(ds).query("SELECT id,payload FROM outbox_event WHERE aggregateid=?",(rs,n)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),original.reminderId()).forEach(e->expected.put(e.getKey(),e.getValue()));assertEquals(3,expected.size());
  var p=new Properties();p.put("bootstrap.servers",System.getenv("BRAIN_TEST_PLANNING_KAFKA_BOOTSTRAP"));p.put("group.id","planning-validation-"+ids.next());p.put("enable.auto.commit","false");p.put("auto.offset.reset","earliest");p.put("key.deserializer","org.apache.kafka.common.serialization.StringDeserializer");p.put("value.deserializer","org.apache.kafka.common.serialization.ByteArrayDeserializer");p.put("security.protocol","SSL");p.put("ssl.endpoint.identification.algorithm","HTTPS");p.put("ssl.truststore.type","PEM");p.put("ssl.truststore.certificates",Files.readString(Path.of("/planning-kafka-test/ca.crt")));p.put("ssl.keystore.type","PEM");p.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/planning-kafka-test/user.crt")));p.put("ssl.keystore.key",Files.readString(Path.of("/planning-kafka-test/user.key")));
  try(var consumer=new KafkaConsumer<String,byte[]>(p)){consumer.subscribe(List.of("planning.reminder.v1"));var found=new HashSet<String>();var versions=new ArrayList<Long>();long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(found.size()<3&&System.nanoTime()<deadline)for(var row:consumer.poll(Duration.ofSeconds(1))){if(!row.key().equals(original.reminderId().toString()))continue;var e=ReminderEventEnvelopeV1.parseFrom(row.value());assertArrayEquals(expected.get(e.getEventId()),row.value());assertEquals("planning-service",e.getProducer());assertEquals("Reminder",e.getAggregateType());assertEquals(row.key(),e.getAggregateId());assertEquals(space.toString(),e.getSpaceId());assertEquals(actor.toString(),e.getActorId());assertEquals(trace,e.getTraceId());assertEquals(1,e.getEventVersion());var v=ReminderChangedPayloadV1.parseFrom(e.getPayload());var pin=v.getVersion()==1?original:v.getVersion()==2?next:retired;assertEquals(pin.remindsAt(),v.getRemindsAt());assertEquals(pin.remindsLocal(),v.getRemindsLocal());assertEquals(pin.remindsOffset(),v.getRemindsOffset());assertEquals(pin.previewHash(),v.getPreviewHash());assertEquals(pin.input().minutesBefore(),v.getMinutesBefore());assertEquals(source.scheduleId().toString(),v.getSchedule().getScheduleId());assertEquals(source.title(),v.getSchedule().getTitle());assertEquals(source.startsLocal(),v.getSchedule().getStartsLocal());assertEquals(source.startsOffset(),v.getSchedule().getStartsOffset());assertEquals(List.of("ReminderCreated","ReminderUpdated","ReminderRetired").get((int)v.getVersion()-1),e.getEventType());for(var h:Map.of("id",e.getEventId(),"trace_id",trace,"schema_group","planning","schema_artifact","reminder-events","schema_version","1").entrySet())assertEquals(h.getValue(),new String(row.headers().lastHeader(h.getKey()).value(),StandardCharsets.UTF_8));if(found.add(e.getEventId()))versions.add(v.getVersion());}assertEquals(expected.keySet(),found);assertEquals(List.of(1L,2L,3L),versions);}
 }
}
